-- Versioned recipe preparations and explicit variants. Existing menu and cooking
-- JSON snapshots are deliberately not rewritten by this migration.
begin;
grant create on schema app_private to week_menu_executor;
create function app_private.preparation_scope(prep jsonb) returns text language sql immutable set search_path='' as $$
 select 'preparation:'||(prep->>'id')||':'||(prep->>'revision')||':'||coalesce((select string_agg(length(coalesce(s->>'en',''))::text||':'||coalesce(s->>'en','')||length(coalesce(s->>'es',''))::text||':'||coalesce(s->>'es',''),'' order by n) from jsonb_array_elements(prep->'instructions') with ordinality x(s,n)),'')
$$;
alter function app_private.preparation_scope(jsonb) owner to week_menu_executor;
revoke all on function app_private.preparation_scope(jsonb) from public,anon,authenticated;
create function app_private.variant_recipe(recipe jsonb,variant jsonb) returns jsonb language sql immutable set search_path='' as $$
 select recipe || jsonb_build_object('name',variant->'name','components',coalesce((
 select jsonb_agg(jsonb_build_object('id',cid,'kind',case when optional then 'dessert' else coalesce((select nullif(c->>'kind','dessert') from jsonb_array_elements(recipe->'components') c where c->>'id'=cid),'main') end,'name',variant->'name','optional',optional,'default_included',included,'ingredients',ingredients,'instructions','[]'::jsonb) order by pos,cid)
 from (select l->>'component_id' cid,bool_and((p->>'optional')::boolean) optional,bool_and((p->>'default_included')::boolean) included,
  min((l->>'order')::integer) pos,
  jsonb_agg(l order by (l->>'order')::integer) ingredients
 from jsonb_array_elements(variant->'preparations') p cross join lateral jsonb_array_elements(p->'lines') l group by l->>'component_id') groups),'[]'::jsonb))
$$;
alter function app_private.validate_recipe(jsonb) rename to validate_recipe_legacy;
create function app_private.validate_recipe(p jsonb) returns void language plpgsql security definer set search_path='' as $$
declare model jsonb:=p->'recipe_model';v jsonb;prep jsonb;line jsonb;other jsonb;begin
 perform app_private.validate_recipe_legacy(p);
 if model is null then return;end if;
 if model->'legacy_components' is distinct from p->'components' or model->'legacy_name' is distinct from p->'name' then raise exception 'recipe_update_required';end if;
 if model->>'version'<>'2' or jsonb_typeof(model->'variants') is distinct from 'array' or jsonb_array_length(model->'variants') not between 1 and 50 then raise exception 'invalid_recipe_model';end if;
 if not exists(select 1 from jsonb_array_elements(model->'variants') x where x->>'id'=model->>'default_variant_id') or (select count(*) from jsonb_array_elements(model->'variants'))<>(select count(distinct x->>'id') from jsonb_array_elements(model->'variants') x) then raise exception 'invalid_recipe_model';end if;
 for v in select * from jsonb_array_elements(model->'variants') loop
  if coalesce(v->>'id','')!~'^[A-Za-z0-9_-]{1,100}$' or jsonb_typeof(v->'preparations') is distinct from 'array' or jsonb_array_length(v->'preparations') not between 1 and 30 or jsonb_typeof(v->'substitutions') is distinct from 'array' then raise exception 'invalid_recipe_model';end if;
  if (select count(*) from jsonb_array_elements(v->'preparations'))<>(select count(distinct x->>'id') from jsonb_array_elements(v->'preparations') x) then raise exception 'invalid_recipe_model';end if;
  for prep in select * from jsonb_array_elements(v->'preparations') loop
   if jsonb_typeof(prep->'name') is distinct from 'object' or coalesce(length(trim(coalesce(nullif(prep->'name'->>'en',''),prep->'name'->>'es'))),0) not between 1 and 160 or exists(select 1 from jsonb_array_elements(prep->'instructions') st where jsonb_typeof(st) is distinct from 'object' or (st ? 'en' and jsonb_typeof(st->'en')<>'string') or (st ? 'es' and jsonb_typeof(st->'es')<>'string')) then raise exception 'invalid_recipe_model';end if;
   if coalesce(prep->>'id','')!~'^[A-Za-z0-9_-]{1,150}$' or jsonb_typeof(prep->'revision') is distinct from 'number' or (prep->>'revision')::numeric<1 or (prep->>'revision')::numeric<>trunc((prep->>'revision')::numeric)
    or jsonb_typeof(prep->'optional') is distinct from 'boolean' or jsonb_typeof(prep->'default_included') is distinct from 'boolean' or jsonb_typeof(prep->'batchable') is distinct from 'boolean' or jsonb_typeof(prep->'soak') is distinct from 'boolean'
    or jsonb_typeof(prep->'lines') is distinct from 'array' or jsonb_array_length(prep->'lines') not between 1 and 100 or jsonb_typeof(prep->'instructions') is distinct from 'array' then raise exception 'invalid_recipe_model';end if;
   for line in select * from jsonb_array_elements(prep->'lines') loop
    if coalesce(line->>'component_id','')='' or jsonb_typeof(line->'order') is distinct from 'number' or (line->>'order')::numeric<0 then raise exception 'invalid_recipe_model';end if;
   end loop;
   -- A preparation revision has one method and food identity across all recipes.
   -- Quantities belong to each recipe; actual ratios are checked when batching.
   for other in select pr from app_private.resolved_saved_recipes r cross join lateral jsonb_array_elements(r.data->'recipe_model'->'variants') va cross join lateral jsonb_array_elements(va->'preparations') pr where pr->>'id'=prep->>'id' and pr->>'revision'=prep->>'revision' loop
    if other->'instructions' is distinct from prep->'instructions' or other->'batchable' is distinct from prep->'batchable' or other->'soak' is distinct from prep->'soak'
     or (select jsonb_agg(jsonb_build_array(l->'ingredient_id',l->'unit') order by l->>'ingredient_id') from jsonb_array_elements(other->'lines') l) is distinct from (select jsonb_agg(jsonb_build_array(l->'ingredient_id',l->'unit') order by l->>'ingredient_id') from jsonb_array_elements(prep->'lines') l) then raise exception 'preparation_revision_conflict';end if;
   end loop;
  end loop;
  if (select count(*) from jsonb_array_elements(v->'preparations') pr cross join lateral jsonb_array_elements(pr->'lines') l)<>(select count(distinct (l->>'component_id',l->>'ingredient_id')) from jsonb_array_elements(v->'preparations') pr cross join lateral jsonb_array_elements(pr->'lines') l) then raise exception 'invalid_recipe_model';end if;
  perform app_private.validate_recipe_legacy(app_private.variant_recipe(p,v));
 end loop;
end$$;
alter function app_private.checked_portion_v2(jsonb,boolean) rename to checked_portion_legacy;
create function app_private.checked_portion_v2(p jsonb,enforce_diet boolean default true) returns jsonb language plpgsql security definer set search_path='' as $$
declare recipe jsonb:=p->'recipe_snapshot';variant jsonb;checked jsonb;expected jsonb;begin
 if p->>'eating_out'='true' or p->>'variant_id' is null then return app_private.checked_portion_legacy(p,enforce_diet);end if;
 select v into variant from jsonb_array_elements(recipe->'recipe_model'->'variants') v where v->>'id'=p->>'variant_id';
 if variant is null then raise exception 'invalid_recipe_model';end if;
 select jsonb_agg(l) into expected from jsonb_array_elements(variant->'preparations') pr cross join lateral jsonb_array_elements(pr->'lines') l where not (pr->>'optional')::boolean or p->>'dessert'='true';
 if (select count(*) from jsonb_array_elements(p->'lines'))<>jsonb_array_length(expected) or (select count(distinct (l->>'component_id',l->>'ingredient_id')) from jsonb_array_elements(p->'lines') l)<>jsonb_array_length(expected)
  or exists(select 1 from jsonb_array_elements(expected) e where not exists(select 1 from jsonb_array_elements(p->'lines') l where l->>'component_id'=e->>'component_id' and l->>'ingredient_id'=e->>'ingredient_id')) then raise exception 'invalid_recipe_model';end if;
 checked:=app_private.checked_portion_legacy(p||jsonb_build_object('recipe_snapshot',app_private.variant_recipe(recipe,variant),'substitutions','[]'::jsonb),enforce_diet);
 return checked||jsonb_build_object('recipe_snapshot',recipe||jsonb_build_object('recipe_model',jsonb_build_object('version',2,'default_variant_id',variant->'id','variants',jsonb_build_array(variant))),'name',variant->'name','substitutions',variant->'substitutions');
end$$;
-- Keep the existing authorization/CAS/history/shopping transaction intact.
alter function app_private.api_save_content(text,jsonb,integer,boolean) rename to api_save_content_legacy;
create function app_private.api_save_content(kind text,p jsonb,expected integer,archive boolean) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=app_private.actor();old jsonb;begin
 if kind='recipe' then
  select data into old from app_private.resolved_saved_recipes where id=p->>'id';
  if old ? 'recipe_model' and not (p ? 'recipe_model') then raise exception 'recipe_update_required';end if;
 end if;
 perform app_private.api_save_content_legacy(kind,p,expected,archive);
end$$;

-- Pinned editorial models; household overrides and saved snapshots are untouched.
update app_private.starter_content c set data=c.data||jsonb_build_object('recipe_model',models.value) from jsonb_each($models${"b01":{"version":2,"legacy_components":[{"id":"main","kind":"main","name":{"en":"Apple and ginger porridge","es":"Gachas de avena con manzana y jengibre"},"optional":false,"default_included":true,"ingredients":[{"ingredient_id":"oats","quantity":50,"unit":"g","variety_role":"base"},{"ingredient_id":"milk","quantity":200,"unit":"g","variety_role":"support"},{"ingredient_id":"apple","quantity":120,"unit":"g","variety_role":"support"},{"ingredient_id":"ginger","quantity":2,"unit":"g","variety_role":"support"},{"ingredient_id":"walnut","quantity":10,"unit":"g","variety_role":"support"}],"instructions":[{"en":"Core and dice the apple; grate the ginger.","es":"Retira el corazón de la manzana, córtala y ralla el jengibre."},{"en":"Simmer the oats, milk, apple and ginger gently for 5–8 minutes, stirring; add a little water if needed.","es":"Cuece suavemente la avena, la leche, la manzana y el jengibre durante 5–8 minutos, removiendo; añade un poco de agua si hace falta."},{"en":"Serve with the measured chopped walnuts.","es":"Sirve con las nueces pesadas y troceadas."}],"reference_energy_kcal":413.38,"reference_energy_kcal_exact":"413.38","dietary_patterns":["omnivore","pescatarian","vegetarian"],"variety_keys":["oats"]}],"legacy_name":{"en":"Apple and ginger porridge","es":"Gachas de avena con manzana y jengibre"},"default_variant_id":"original","variants":[{"id":"original","name":{"en":"Apple and ginger porridge","es":"Gachas de avena con manzana y jengibre"},"substitutions":[],"preparations":[{"id":"b01-main","revision":1,"name":{"en":"Apple and ginger porridge","es":"Gachas de avena con manzana y jengibre"},"optional":false,"default_included":true,"lines":[{"ingredient_id":"oats","quantity":50,"unit":"g","variety_role":"base","component_id":"main","order":0},{"ingredient_id":"milk","quantity":200,"unit":"g","variety_role":"support","component_id":"main","order":1},{"ingredient_id":"apple","quantity":120,"unit":"g","variety_role":"support","component_id":"main","order":2},{"ingredient_id":"ginger","quantity":2,"unit":"g","variety_role":"support","component_id":"main","order":3},{"ingredient_id":"walnut","quantity":10,"unit":"g","variety_role":"support","component_id":"main","order":4}],"instructions":[{"en":"Core and dice the apple; grate the ginger.","es":"Retira el corazón de la manzana, córtala y ralla el jengibre."},{"en":"Simmer the oats, milk, apple and ginger gently for 5–8 minutes, stirring; add a little water if needed.","es":"Cuece suavemente la avena, la leche, la manzana y el jengibre durante 5–8 minutos, removiendo; añade un poco de agua si hace falta."},{"en":"Serve with the measured chopped walnuts.","es":"Sirve con las nueces pesadas y troceadas."}],"batchable":true,"soak":false}]},{"id":"s19","name":{"en":"Apple and ginger porridge · pumpkin seeds","es":"Gachas de avena con manzana y jengibre · pipas de calabaza"},"substitutions":[{"from":"walnut","to":"pumpkin_seed","instructions":{"en":"Replace walnuts with pumpkin seeds.","es":"Sustituye nueces por pipas de calabaza."}}],"preparations":[{"id":"b01-main-s19","revision":1,"name":{"en":"Apple and ginger porridge · pumpkin seeds","es":"Gachas de avena con manzana y jengibre · pipas de calabaza"},"optional":false,"default_included":true,"lines":[{"ingredient_id":"oats","quantity":50,"unit":"g","variety_role":"base","component_id":"main","order":0},{"ingredient_id":"milk","quantity":200,"unit":"g","variety_role":"support","component_id":"main","order":1},{"ingredient_id":"apple","quantity":120,"unit":"g","variety_role":"support","component_id":"main","order":2},{"ingredient_id":"ginger","quantity":2,"unit":"g","variety_role":"support","component_id":"main","order":3},{"ingredient_id":"pumpkin_seed","unit":"g","quantity":10,"component_id":"main","order":4}],"instructions":[{"en":"Core and dice the apple; grate the ginger.","es":"Retira el coraz