"basil","quantity":5,"unit":"g","component_id":"main","order":11},{"ingredient_id":"pine_nuts","quantity":10,"unit":"g","component_id":"main","order":12},{"ingredient_id":"salt","quantity":4,"unit":"g","component_id":"main","order":13},{"ingredient_id":"black_pepper","quantity":0.6,"unit":"g","component_id":"main","order":14}],"instructions":[{"en":"Brown chicken; soften onion and garlic. Add tomatoes and wine, then stock, cream and gnocchi. Return chicken and bake at 220°C until its centre reaches 75°C.","es":"Dora el pollo y rehoga cebolla y ajo. Añade tomates, vino, caldo, nata y ñoquis. Reincorpora el pollo y hornea a 220°C hasta alcanzar 75°C en el centro."},{"en":"Mix in some pesto, add mozzarella and bake four minutes more. Slice chicken and finish with remaining pesto, basil and pine nuts.","es":"Mezcla parte del pesto, añade mozzarella y hornea cuatro minutos más. Corta el pollo y termina con pesto restante, albahaca y piñones."}],"batchable":false,"soak":false}]}]}}$models$::jsonb) models where c.kind='recipe' and c.id=models.key;
create or replace function app_private.cooking_requirements(settings jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare result jsonb:='[]'; m record;p jsonb; person record;recipe jsonb;rule jsonb;method jsonb;lines jsonb;selection jsonb;base jsonb; choices jsonb;g numeric; signature text; scope text;rice boolean;prep jsonb;variant jsonb;begin
 for m in select * from public.meal_plans where day>=current_date-40 order by day,meal_type loop
  for p in select * from jsonb_array_elements(m.data->'portions') loop
   if coalesce((p->>'eating_out')::boolean,false) then continue;end if;
   select x.*,app_private.effective_profile(x.id) as profile into person from public.members x where x.id=(p->>'member_id')::uuid and status='active' and onboarded;
   if not found or person.profile is null then continue;end if;
   select data into recipe from app_private.resolved_saved_recipes where id=p->>'recipe_id' and not archived;
   if not found or exists(select 1 from app_private.recipe_vetoes where recipe_id=p->>'recipe_id' and banned) then continue;end if;
   if exists(select 1 from jsonb_array_elements(p->'lines') l left join app_private.resolved_food_items f on f.id=l->>'ingredient_id' where f.id is null or f.archived or not (f.data->'dietary_patterns' ? (person.profile->>'diet')) or person.profile->'excluded_ingredients' ? (l->>'ingredient_id')) then continue;end if;
   recipe:=coalesce(nullif(p->'recipe_snapshot','null'),recipe);
   select data into rule from app_private.cooking_rules where recipe_id=p->>'recipe_id';
   if p->>'variant_id' is null then
   if not found then continue;end if;
   select jsonb_agg(jsonb_build_object('id',c->'id','instructions',c->'instructions') order by ord) into method from jsonb_array_elements(recipe->'components') with ordinality x(c,ord);
   if method is distinct from rule->'method' then continue;end if;
   select jsonb_agg(jsonb_build_object('id',c->'id','ingredients',(select jsonb_agg(jsonb_build_object('ingredient_id',i->'ingredient_id','unit',i->'unit') order by n) from jsonb_array_elements(c->'ingredients') with ordinality x(i,n))) order by ord) into method from jsonb_array_elements(recipe->'components') with ordinality x(c,ord);
   if method is distinct from rule->'ingredients' then continue;end if;
   select coalesce(jsonb_agg(l order by ord),'[]') into lines from jsonb_array_elements(p->'lines') with ordinality x(l,ord) where exists(select 1 from jsonb_array_elements(recipe->'components') c where c->>'id'=l->>'component_id' and c->>'kind'<>'dessert');
   choices:='[]';
   for base in select * from jsonb_array_elements(rule->'bases') loop
    select jsonb_agg(l) into selection from jsonb_array_elements(lines) l where l->>'ingredient_id'=base->>'ingredient_id' and l->>'component_id'=base->>'component_id';
    if selection is not null then choices:=choices||jsonb_build_array(jsonb_build_object('scope','base:'||(base->>'ingredient_id')||':plain_boiled','lines',selection,'name',selection->0->'name','kind','base','soak',base->'soak'));end if;
   end loop;
   if (rule->>'whole')::boolean and jsonb_array_length(coalesce(p->'substitutions','[]'))=0 and ((settings->>'prefer_whole')::boolean or jsonb_array_length(choices)=0) then
    choices:=jsonb_build_array(jsonb_build_object('scope','whole','lines',lines,'name',p->'name','kind','recipe','soak',exists(select 1 from jsonb_array_elements(rule->'bases') b where (b->>'soak')::boolean)));
   end if;
   else
    select v into variant from jsonb_array_elements(recipe->'recipe_model'->'variants') v where v->>'id'=p->>'variant_id';
    choices:='[]';
    for prep in select * from jsonb_array_elements(variant->'preparations') loop
     if (prep->>'optional')::boolean or not (prep->>'batchable')::boolean then continue;end if;
     select jsonb_agg(l order by n) into selection from jsonb_array_elements(p->'lines') with ordinality x(l,n) where exists(select 1 from jsonb_array_elements(prep->'lines') r where r->>'component_id'=l->>'component_id' and r->>'ingredient_id'=l->>'ingredient_id');
     if selection is not null then choices:=choices||jsonb_build_array(jsonb_build_object('scope',app_private.preparation_scope(prep),'lines',selection,'name',prep->'name','kind',case when jsonb_array_length(prep->'lines')=1 then 'base' else 'recipe' end,'soak',prep->'soak','instructions',prep->'instructions'));end if;
    end loop;
    if (settings->>'prefer_whole')::boolean and (select count(*) from jsonb_array_elements(variant->'preparations') pr where not (pr->>'optional')::boolean)>1 and not exists(select 1 from jsonb_array_elements(variant->'preparations') pr where not (pr->>'optional')::boolean and not (pr->>'batchable')::boolean) then
     select jsonb_build_object('id','whole-'||(recipe->>'id')||'-'||(variant->>'id'),'revision',coalesce(recipe->'revision','1'::jsonb),'instructions',(select jsonb_agg(step order by n,k) from jsonb_array_elements(variant->'preparations') with ordinality x(pr,n) cross join lateral jsonb_array_elements(pr->'instructions') with ordinality y(step,k) where not (pr->>'optional')::boolean)) into prep;
     select jsonb_agg(l order by n) into selection from jsonb_array_elements(p->'lines') with ordinality x(l,n) where exists(select 1 from jsonb_array_elements(variant->'preparations') pr cross join lateral jsonb_array_elements(pr->'lines') r where not (pr->>'optional')::boolean and r->>'component_id'=l->>'component_id' and r->>'ingredient_id'=l->>'ingredient_id');
     choices:=jsonb_build_array(jsonb_build_object('scope',app_private.preparation_scope(prep),'lines',selection,'name',variant->'name','kind','recipe','soak',exists(select 1 from jsonb_array_elements(variant->'preparations') pr where not (pr->>'optional')::boolean and (pr->>'soak')::boolean),'instructions',prep->'instructions'));
    end if;
   end if;
   for selection in select * from jsonb_array_elements(choices) loop
    lines:=selection->'lines';scope:=selection->>'scope';
    select sum((l->>'grams')::numeric),bool_or(l->>'ingredient_id' like 'rice_%') into g,rice from jsonb_array_elements(lines) l;
    if g is null or g<=0 then continue;end if;
    select md5(jsonb_build_array(scope,case when scope='whole' then recipe->>'id' else '' end,jsonb_agg(jsonb_build_array(l->'ingredient_id',l->'reference_state',l->'quantity_basis',(l->>'nutrition_revision')::integer,trim_scale((l->>'energy_per_100g')::numeric),trim_scale((l->>'grams')::numeric/gcd((l->>'grams')::numeric,g))::text||'/'||trim_scale(g/gcd((l->>'grams')::numeric,g))::text) order by l->>'ingredient_id',l->>'component_id'))::text) into signature from jsonb_array_elements(lines) l;
    result:=result||jsonb_build_array(selection||jsonb_build_object('id',m.day||'/'||m.meal_type||'/'||person.id||'/'||scope,'day',m.day,'type',m.meal_type,'member_id',person.id,'member',person.name,'recipe_id',recipe->>'id','recipe',p->'name','grams',g,'signature',signature,'menu_signature',md5(app_private.cooking_normalize(lines)::text),'fridge_hours',case when rice then 24 else 48 end,'cool_hours',case when rice then 1 else 2 end,'due_at',((m.day::text||' '||coalesce(person.meal_times->>m.meal_type,case m.meal_type when 'breakfast' then '09:00' when 'lunch' then '14:00' else '21:00' end))::timestamp at time zone (settings->>'timezone')),'instructions',coalesce(selection->'instructions',case when scope='whole' then (select jsonb_agg(i) from jsonb_array_elements(recipe->'components') c cross join lateral jsonb_array_elements(c->'instructions') i where c->>'kind'<>'dessert') else '[{"en":"Weigh dry; cook separately according to the packet, cool promptly and divide before storing.","es":"Pesa en seco; cuece aparte según el envase, enfría pronto y reparte antes de guardar."}]'::jsonb end)));
   end loop;
  end loop;
 end loop;return result;
end$$;
create function app_private.variant_transfer_portion(rid text,uid uuid,d date,t text,wants_dessert boolean,preferred text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare snapshot jsonb;variant jsonb;recipe jsonb; rev integer; profile jsonb; budget numeric; c jsonb; l jsonb; f jsonb; original jsonb; cv jsonb; rule jsonb;
 raw jsonb:='[]'; lines jsonb:='[]'; subs jsonb:='[]'; quantity numeric; unit text; energy numeric; total numeric:=0; factor numeric; step numeric; scaled numeric; item jsonb;
begin
 select app_private.effective_profile(id) into profile from public.members where id=uid and status='active' and onboarded;
 if profile is null then raise exception 'invalid_member';end if;
 select data,revision into recipe,rev from app_private.resolved_saved_recipes where id=rid and not archived;
 if recipe is null or not (recipe->'meal_types') ? t then raise exception 'archived_ingredient';end if;
 recipe:=recipe||jsonb_build_object('revision',rev,'archived',false);
 budget:=coalesce((select kcal from public.budget_overrides where member_id=uid and day=d and meal_type=t),
  (select (budgets->>t)::numeric from public.targets where member_id=uid and effective_date<=d order by effective_date desc,created_at desc,id desc limit 1));
 if budget is null or budget<=0 then raise exception 'invalid_budgets';end if;
 snapshot:=recipe;
 if recipe->'recipe_model' is not null then
  select v into variant from jsonb_array_elements(recipe->'recipe_model'->'variants') v where not exists(
   select 1 from jsonb_array_elements(v->'preparations') pr cross join lateral jsonb_array_elements(pr->'lines') li left join app_private.resolved_food_items f on f.id=li->>'ingredient_id'
   where (not (pr->>'optional')::boolean or wants_dessert) and (f.id is null or f.archived or not (f.data->'dietary_patterns') ? (profile->>'diet') or (profile->'excluded_ingredients') ? f.id))
  order by case when v->>'id'=preferred then -2 when v->>'id'=recipe->'recipe_model'->>'default_variant_id' then -1 else jsonb_array_length(v->'substitutions') end,v->>'id' limit 1;
  if variant is null then raise exception 'no_compatible_variant';end if;
  recipe:=app_private.variant_recipe(recipe,variant);
 end if;
 for c in select value from jsonb_array_elements(recipe->'components') loop
  if coalesce((c->>'optional')::boolean,false) and not coalesce(case when c->>'kind'='dessert' then wants_dessert else (c->>'default_included')::boolean end,false) then continue;end if;
  for l in select value from jsonb_array_elements(c->'ingredients') loop
   select data into f from app_private.resolved_food_items where id=l->>'ingredient_id' and not archived;
   if f is null then raise exception 'archived_ingredient';end if;
   quantity:=(l->>'quantity')::numeric;unit:=l->>'unit';
   select value into cv from jsonb_array_elements(f->'conversions') where value->>'unit'=unit;
   if cv is null then raise exception 'missing_conversion';end if;
   if not (f->'dietary_patterns') ? (profile->>'diet') or coalesce(profile->'excluded_ingredients','[]') ? (f->>'id') then
    original:=f;
    select r.data into rule from app_private.resolved_substitution_rules r join app_private.resolved_food_items dest on dest.id=r.data->>'to_ingredient_id' and not dest.archived
     where r.data->>'from_ingredient_id'=f->>'id' and (r.data->'allowed_recipe_ids') ? rid
      and (dest.data->'dietary_patterns') ? (profile->>'diet') and not coalesce(profile->'excluded_ingredients','[]') ? dest.id order by r.id limit 1;
    if rule is null then raise exception 'no_suitable_recipe';end if;
    quantity:=quantity*(cv->>'grams_per_unit')::numeric*(rule->>'initial_target_grams_per_source_gram')::numeric;unit:='g';
    select data into f from app_private.resolved_food_items where id=rule->>'to_ingredient_id' and not archived;
    select value into cv from jsonb_array_elements(f->'conversions') where value->>'unit'=unit;
    if cv is null then raise exception 'missing_conversion';end if;
    subs:=subs||jsonb_build_array(jsonb_build_object('from',original->>'id','to',f->>'id','instructions',rule->'instruction_override'));
   end if;
   energy:=(f->'nutrition_per_100g'->>'energy_kcal')::numeric;
   if energy is null or energy<0 then raise exception 'missing_nutrition';end if;
   total:=total+quantity*(cv->>'grams_per_unit')::numeric*energy/100;
   raw:=raw||jsonb_build_array(jsonb_build_object('ingredient_id',f->>'id','component_id',c->>'id','quantity',quantity,'unit',unit,'conversion',cv));
  end loop;
 end loop;
 if total<=0 then raise exception 'missing_nutrition';end if;factor:=budget/total;
 for item in select value from jsonb_array_elements(raw) loop
  scaled:=(item->>'quantity')::numeric*factor;unit:=item->>'unit';
  if unit in('kg','l') then
   scaled:=scaled*1000;step:=case when scaled>=10 then 10 when scaled<1 then 0.1 else 1 end;quantity:=greatest(round(scaled/step)*step,step)/1000;
  else
   step:=case when unit in('g','ml') then case when scaled>=10 then 10 when scaled<1 then 0.1 else 1 end else coalesce((item->'conversion'->>'quantity_step')::numeric,1) end;
   if step<=0 then raise exception 'invalid_quantity';end if;quantity:=round(scaled/step)*step; if unit in('g','ml') and scaled<1 then quantity:=greatest(quantity,0.1);end if;
  end if;
  if quantity<=0 then raise exception 'quantity_needs_review';end if;
  lines:=lines||jsonb_build_array((item-'conversion')||jsonb_build_object('quantity',quantity));
 end loop;
 return app_private.checked_portion(jsonb_build_object('member_id',uid,'recipe_id',rid,'recipe_snapshot',snapshot,'variant_id',variant->'id','name',recipe->'name','budget',budget,'dessert',wants_dessert,'eating_out',false,'lines',lines,'substitutions',coalesce(variant->'substitutions',subs)));
end$$;

alter function app_private.variant_transfer_portion(text,uuid,date,text,boolean,text) owner to week_menu_executor;
revoke all on function app_private.variant_transfer_portion(text,uuid,date,text,boolean,text) from public,anon,authenticated;
create or replace function app_private.transfer_portion(rid text,uid uuid,d date,t text,wants_dessert boolean) returns jsonb language sql security definer set search_path='' as $$select app_private.variant_transfer_portion(rid,uid,d,t,wants_dessert,null)$$;
do $patch$declare body text;begin
 body:=pg_get_functiondef('app_private.transfer_patch(jsonb,jsonb,jsonb)'::regprocedure);
 if position('p:=app_private.transfer_portion(' in body)=0 then raise exception 'variant_transfer_definition_mismatch';end if;
 body:=replace(body,'p:=app_private.transfer_portion(choice->>''recipe_id'',member.id,(ep->>''day'')::date,ep->>''type'',dessert);','p:=app_private.variant_transfer_portion(choice->>''recipe_id'',member.id,(ep->>''day'')::date,ep->>''type'',dessert,choice->''variants''->>member.id::text);');
 execute body;
 body:=pg_get_functiondef('app_private.transfer_choice(jsonb,jsonb)'::regprocedure);
 body:=replace(body,'''desserts'',desserts);','''desserts'',desserts,''variants'',coalesce((select jsonb_object_agg(p->>''member_id'',p->>''variant_id'') from jsonb_array_elements(portions) p where p->>''variant_id'' is not null),''{}''::jsonb));');
 execute body;
end$patch$;
alter function app_private.variant_recipe(jsonb,jsonb) owner to week_menu_executor;
revoke all on function app_private.variant_recipe(jsonb,jsonb) from public,anon,authenticated;
alter function app_private.validate_recipe(jsonb) owner to week_menu_executor;
revoke all on function app_private.validate_recipe(jsonb) from public,anon,authenticated;
alter function app_private.checked_portion_v2(jsonb,boolean) owner to week_menu_executor;
revoke all on function app_private.checked_portion_v2(jsonb,boolean) from public,anon,authenticated;
alter function app_private.api_save_content(text,jsonb,integer,boolean) owner to week_menu_executor;
revoke all on function app_private.api_save_content(text,jsonb,integer,boolean) from public,anon,authenticated;
grant execute on function app_private.api_save_content(text,jsonb,integer,boolean) to authenticated;
revoke all on function app_private.api_save_content_legacy(text,jsonb,integer,boolean) from public,anon,authenticated;
do $patch$declare body text;begin
 body:=pg_get_functiondef('app_private.api_cooking_command(uuid,uuid,uuid,bigint,text,jsonb)'::regprocedure);
 if position('if jsonb_array_length(settings->''sessions'')>14' in body)=0 then raise exception 'recipe_cooking_settings_definition_mismatch';end if;
 body:=replace(body,'if jsonb_array_length(settings->''sessions'')>14','if (settings ? ''prioritize_preparations'' and jsonb_typeof(settings->''prioritize_preparations'')<>''boolean'') or jsonb_array_length(settings->''sessions'')>14');
 execute body;
end$patch$;
revoke create on schema app_private from week_menu_executor;
notify pgrst,'reload schema';
commit;
